  {Env e=new Env();API api=new API();e.access().record(row(SID,e.time.get()+2,9000));api.pages.put(0,new JSONArray().put(remote(row(SID,e.time.get(),2000))));sync(e,api);ok(api.uploads.size()==2,"newer local uploads after read");ok(e.access().rows().getJSONObject(0).getLong("positionMs")==9000,"newer offline progress retained");group("local newer survives pull");}
  {Env e=new Env();API api=new API();api.pages.put(0,new JSONArray().put(remote(row(SID,e.time.get(),1000))));api.pages.put(500,new JSONArray().put(remote(row("12345678901234567890",e.time.get()+1,2000))));sync(e,api);ok(e.access().rows().length()==2,"all history pages included");ok(Collections.frequency(api.calls,"/reading/bookapi/read_history/list/v")==2,"fallback offset advances500 not batchlength");ok(api.uploads.isEmpty(),"read-only sync makes no write");group("complete history pagination");}
  {Env e=new Env();e.access().record(row(SID,e.time.get(),1000));String before=e.disk.values.get(UID).toString();API api=new API();api.pages.put(0,new JSONArray().put(remote(row(SID,e.time.get()+10,9000))));api.repeatPage=true;bad(()->sync(e,api),"repeated page");ok(before.equals(e.disk.values.get(UID).toString()),"incomplete snapshot leaves disk unchanged");ok(e.access().rows().getJSONObject(0).getLong("positionMs")==1000,"incomplete snapshot not merged");API empty=new API();empty.moreWithEmpty=true;bad(()->sync(e,empty),"empty more");ok(e.library.status().getInt("pendingCount")==1,"paging errors preserve outbox");group("repeated and incomplete pages reject snapshot");}
